properties.script:
importPackage(com.jcraft.jsch);

// ===== Aetna SFTP Bridge =====
// Steps 1-3: login to Aetna's inbound SFTP, scan for new files, and copy anything found
// into the Aetna landing directory that the existing "Aetna" channel already watches.
// Step 4: when nothing is found, decide whether an "Aetna file missing" alert is warranted.
// Any failure in steps 1-3 (login, scan, or copy) sends an email alert.

// Aetna's per-MCO folder segment in the S3-backed landing bucket. Put in globalMap (not
// channelMap - channelMap is scoped to an in-flight message, and this poll script runs
// before any message exists yet, so channelMap is not defined here) so the "Copy to Aetna
// Landing" destination's <host> (${s3BucketName}/${mcoSftpS3Folder}/esmf/inbound) can
// reference it too, keeping a single place to change if this ever needs updating.
var mcoSftpS3Folder = 'mco-sftp-aetna';
globalMap.put('mcoSftpS3Folder', mcoSftpS3Folder);

function sendAlertEmail(subject, body) {
    try {
        var smtpHostname = configurationMap.get('smtpHostName');
        var smtpPort = parseInt(configurationMap.get('smtpPort'));
        var smtpUsername = configurationMap.get('smtpUsername');
        var smtpPassword = configurationMap.get('smtpPassword');
        var fromEmail = configurationMap.get('smtpFromEmail');
        var toEmail = 'engineering@techbd.org';

        var smtpConn = SMTPConnection(smtpHostname, smtpPort, 0, true, 'TLS', smtpUsername, smtpPassword, fromEmail);
        smtpConn.send(toEmail, '', fromEmail, subject, body, 'UTF-8');
        logger.info('Aetna SFTP Bridge: alert email sent - ' + subject);
    } catch (mailErr) {
        logger.error('Aetna SFTP Bridge: failed to send alert email - ' + mailErr);
    }
}

// Same startDate/endDate windowed reporting-month calculation used across the MCO channels
// (see Aetna.xml's getFolderName), duplicated here since this channel has no other dependency
// on that shared code template library.
function getFolderName(year, month, date) {
    var months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
    var startDate = parseInt(configurationMap.get('startDate'));
    var endDate = parseInt(configurationMap.get('endDate'));

    if (startDate >= endDate) {
        if (date >= startDate) {
            if (month != 11) {
                month = month + 1;
            } else {
                month = 0;
                year = year + 1;
            }
        }
    }
    return months[month] + '-' + year;
}

// True if Aetna already has a fully/partially processed batch for the current reporting month
function alreadyProcessedThisMonth() {
    var jdbdcDriver = configurationMap.get('jdbdcDriver');
    var jbdcUrl = globalMap.get('jbdcUrl');
    var dbName = globalMap.get('dbName');
    var dbPassword = globalMap.get('dbPassword');
    var dbConn;

    try {
        dbConn = DatabaseConnectionFactory.createDatabaseConnection(jdbdcDriver, jbdcUrl, dbName, dbPassword);

        var tenantResult = dbConn.executeCachedQuery(
            "select tenant_id from techbd_udi_ingress.tenants where tenant_short_code = ? and is_active = '1'",
            ['AET']
        );
        var mcoId = null;
        while (tenantResult.next()) {
            mcoId = tenantResult.getString(1);
        }
        if (!mcoId) {
            logger.info('Aetna SFTP Bridge: could not resolve tenant_id for AET, treating as not processed this month');
            return false;
        }

        var recordResult = dbConn.executeCachedQuery(
            "select status, created_on_utc from mco_data.mco_records where tenant_id = ? and is_active = '1' ORDER BY batch_id DESC LIMIT 1",
            [mcoId]
        );
        var status = null;
        var createdOnUtc = null;
        while (recordResult.next()) {
            status = recordResult.getString(1);
            createdOnUtc = recordResult.getString(2);
        }

        if (!createdOnUtc || (status != 'FULLY_PROCESSED' && status != 'PARTIALLY_PROCESSED')) {
            return false;
        }

        var createdParts = (createdOnUtc + '').split(' ')[0].split('-');
        var folderNameFromDB = getFolderName(parseInt(createdParts[0]), parseInt(createdParts[1]) - 1, parseInt(createdParts[2]));

        var today = new Date();
        var presentFolderName = getFolderName(today.getFullYear(), today.getMonth(), today.getDate());

        return folderNameFromDB == presentFolderName;
    } finally {
        if (dbConn) {
            dbConn.close();
        }
    }
}

// True when today falls within the monthly submission window (e.g. the 26th through the 5th)
function isWithinSubmissionWindow() {
    var today = new Date();
    var dayOfMonth = today.getDate();
    var startDate = parseInt(configurationMap.get('startDate'));
    var endDate = parseInt(configurationMap.get('endDate'));

    if (startDate >= endDate) {
        // Window wraps across the end of the month, e.g. 26th through the 5th of next month
        return dayOfMonth >= startDate || dayOfMonth <= endDate;
    }
    return dayOfMonth >= startDate && dayOfMonth <= endDate;
}

// Step 4: no files were found on this poll. Never sends the "channel error" alert - only logs.
function handleNoFilesFound() {
    try {
        if (alreadyProcessedThisMonth()) {
            logger.info('Aetna SFTP Bridge: folder checked, no file found - Aetna file already processed for the current reporting month.');
            return;
        }

        if (isWithinSubmissionWindow()) {
            logger.info('Aetna SFTP Bridge: folder checked, no file found, within the submission window - sending alert.');
            sendAlertEmail(
                'Aetna Alert: No ESMF File Found',
                'This is an automated notification that no Aetna ESMF file has been found on Aetna\'s SFTP for the current reporting month as of ' + new Date().toString() + '.\n\nPlease follow up with Aetna if a file was expected.'
            );
        } else {
            logger.info('Aetna SFTP Bridge: folder checked, no file found.');
        }
    } catch (checkErr) {
        // A failure here is a step-4 problem, not a login/scan/copy (steps 1-3) problem, so we
        // only log it rather than sending the step 1-3 error alert.
        logger.error('Aetna SFTP Bridge: error while checking already-processed status for the current month - ' + checkErr);
    }
}

// ===== Main poll: steps 1-3 =====
var sftpHost = configurationMap.get('aetnaInboundSftpHost');
var sftpPort = parseInt(configurationMap.get('aetnaInboundSftpPort'));
var sftpUsername = configurationMap.get('aetnaInboundSftpUsername');
var sftpPassword = configurationMap.get('aetnaInboundSftpPassword');
var sftpFolder = configurationMap.get('aetnaInboundSftpFolder');

var s3BucketName = globalMap.get('s3BucketName');
// Log-only - must match the "Copy to Aetna Landing" destination's <host>, which is what
// actually controls where the file is written (it references ${mcoSftpS3Folder} separately).
var s3LandingPrefix = mcoSftpS3Folder + '/esmf/inbound/';

var session = null;
var sftpChannel = null;

try {
    // Step 1: login to Aetna's SFTP - username/password only, no key-based auth
    var jsch = new JSch();

    session = jsch.getSession(sftpUsername, sftpHost, sftpPort);
    if (sftpPassword) {
        session.setPassword(sftpPassword);
    }
    session.setConfig('StrictHostKeyChecking', 'no');
    // With no identity ever registered (key-based auth removed), JSch still tries
    // 'publickey' first because the server advertises it first, and having zero
    // identities to offer for it makes JSch abort the whole login immediately instead of
    // falling through to 'password' - confirmed via the full JSch protocol log: "Next
    // authentication method: publickey" is followed straight by "Disconnecting", with no
    // "Next authentication method: password" ever appearing. Restricting the preferred
    // methods to password only stops JSch from attempting publickey at all.
    session.setConfig('PreferredAuthentications', 'password');

    // Diagnostic - safe fields only, never logs the password value itself
    logger.info('Aetna SFTP Bridge: connecting to ' + sftpHost + ':' + sftpPort + ' as "' + sftpUsername + '" (password=' + (sftpPassword ? 'present' : 'absent') + ')');

    session.connect(10000);
    logger.info('Aetna SFTP Bridge: SSH handshake and authentication succeeded, server version: ' + session.getServerVersion());

    sftpChannel = session.openChannel('sftp');
    sftpChannel.connect(10000);

    // Step 2: scan folder for new files
    logger.info('Aetna SFTP Bridge: scanning folder "' + sftpFolder + '"');
    var entries = sftpChannel.ls(sftpFolder);
    logger.info('Aetna SFTP Bridge: folder listing returned ' + entries.size() + ' entr' + (entries.size() === 1 ? 'y' : 'ies'));
    var newFiles = [];
    for (var i = 0; i < entries.size(); i++) {
        var entry = entries.get(i);
        if (entry.getAttrs().isDir()) {
            continue;
        }
        var fname = entry.getFilename();
        if (fname == '.' || fname == '..') {
            continue;
        }
        newFiles.push(fname);
    }

    if (newFiles.length === 0) {
        // Step 4: no files exist
        handleNoFilesFound();
        return null;
    }

    // Step 3: copy the file to the Aetna landing directory in the S3-backed SFTP.
    // AmazonS3ClientBuilder is not reachable from this connector's own script (confirmed:
    // neither Packages.com.amazonaws.services.s3.AmazonS3ClientBuilder nor an explicit
    // importPackage resolves it here, even though com.jcraft.jsch resolves fine), so the
    // native "Copy to Aetna Landing" File Writer destination (scheme=S3) performs the
    // actual write, the same way every S3 write elsewhere in the MCO channels is done.
    //
    // A poll can only return one message, so only the first file found is processed here.
    // router.routeMessage(channelId, ...) was tried first to self-route every file found in
    // one poll, but Mirth's VMRouter cannot resolve a channel routing to itself while that
    // same channel's own source poll is still executing - confirmed via the server log:
    // "Could not find channel to route to for channel name: <this channel's own id>",
    // logged server-side without throwing a catchable exception back into this script, so
    // the file was silently never delivered even though this script logged success. Any
    // additional files simply wait for the next poll, 60 seconds later.
    if (newFiles.length > 1) {
        logger.info('Aetna SFTP Bridge: found ' + newFiles.length + ' files this poll - processing the first now, the rest will be picked up on later polls');
    }

    var remoteFileName = newFiles[0];
    try {
        var baos = new java.io.ByteArrayOutputStream();
        sftpChannel.get(sftpFolder + '/' + remoteFileName, baos);
        var fileContent = new java.lang.String(baos.toByteArray(), 'UTF-8');

        // Archive the source file on Aetna's SFTP so it is not re-copied on the next poll.
        // This happens regardless of whether the landing-directory write below succeeds -
        // the "Log Delivery" destination checks that outcome and sends the error alert if
        // the write itself failed, so the failure is not silently lost even though the
        // source file is moved either way.
        try {
            sftpChannel.mkdir(sftpFolder + '/processed');
        } catch (mkdirErr) {
            // Directory most likely already exists
        }
        var processedPath = sftpFolder + '/processed/' + remoteFileName;
        try {
            sftpChannel.rename(sftpFolder + '/' + remoteFileName, processedPath);
        } catch (renameErr) {
            // Most SFTP servers refuse to rename onto an existing target rather than
            // overwriting it - confirmed via repeated identical SftpException failures
            // (message = the destination path) on every poll for the same filename, which
            // otherwise leaves the source file stuck in place and retried forever. Remove
            // whatever is already sitting at the processed path (e.g. left over from a
            // prior run, or a same-named file from an earlier month) and retry once.
            logger.info('Aetna SFTP Bridge: rename to ' + processedPath + ' failed (' + renameErr + '), removing any existing file at that path and retrying');
            try {
                sftpChannel.rm(processedPath);
            } catch (rmErr) {
                // Nothing to remove, or removal itself failed - the retry below will
                // surface whatever the real problem is if this wasn't the cause
            }
            sftpChannel.rename(sftpFolder + '/' + remoteFileName, processedPath);
        }

        logger.info('Aetna SFTP Bridge: delivering ' + remoteFileName + ' to ' + s3BucketName + '/' + s3LandingPrefix);

        var sourceMap = new java.util.HashMap();
        sourceMap.put('originalFilename', remoteFileName);
        return new RawMessage(fileContent, null, sourceMap);
    } catch (fileErr) {
        logger.error('Aetna SFTP Bridge: failed to read/deliver ' + remoteFileName + ' - ' + fileErr);
        sendAlertEmail(
            'Aetna SFTP Bridge Alert: Error Copying File',
            'An error occurred while reading ' + remoteFileName + ' from Aetna\'s SFTP or delivering it to the Aetna landing directory.\n\n' + fileErr
        );
        return null;
    }
} catch (err) {
    // Steps 1-3 error (login, scan, or the overall copy pass)
    logger.error('Aetna SFTP Bridge: error during SFTP login/scan/copy - ' + err);

    // Extra diagnostic detail - each wrapped separately so a failure logging one doesn't
    // hide the others or mask the original error above.
    try {
        if (err.javaException) {
            logger.error('Aetna SFTP Bridge: underlying Java exception - ' + err.javaException + ' (class: ' + err.javaException.getClass().getName() + ')');
            var cause = err.javaException.getCause();
            if (cause) {
                logger.error('Aetna SFTP Bridge: caused by - ' + cause);
            }
        }
    } catch (logErr1) {
        logger.error('Aetna SFTP Bridge: could not introspect underlying exception - ' + logErr1);
    }
    try {
        if (session) {
            logger.error('Aetna SFTP Bridge: session state - serverVersion=' + session.getServerVersion() + ', isConnected=' + session.isConnected());
        }
    } catch (logErr2) {
        logger.error('Aetna SFTP Bridge: could not read session state - ' + logErr2);
    }

    sendAlertEmail(
        'Aetna SFTP Bridge Alert: Channel Error',
        'An error occurred while logging into Aetna\'s SFTP, scanning for new files, or copying files to the Aetna landing directory.\n\n' + err
    );
    return null;
} finally {
    if (sftpChannel) {
        sftpChannel.disconnect();
    }
    if (session) {
        session.disconnect();
    }
}

com.mirth.connect.plugins.javascriptstep.script:
// Runs right before the native S3 write is attempted, so "starting" is logged
// even if the write itself then hangs, times out, or fails before any response exists.
//
// Checks whether the destination S3 object already exists so a replace can be called out
// explicitly in the log, per requirement. The native File Writer destination below
// (errorOnExists=false, outputAppend=false, temporary=false) always overwrites an existing
// object at this key without erroring - the same settings used by every other S3 write in
// the MCO channels (see Aetna.xml's Success/Error Data destinations) - so this check does
// not change the write behavior, it only makes a replace visible in the logs.
// AmazonS3ClientBuilder is not reachable from the source JavaScript Reader connector's own
// script on this Bridgelink instance (see this channel's description), but it is reachable
// here since this is a destination transformer step, same as Aetna.xml's transformer-step
// scripts that already use it successfully.
var uploadFileName = $('originalFilename');
var uploadBucket = globalMap.get('s3BucketName');
var uploadKey = globalMap.get('mcoSftpS3Folder') + '/esmf/inbound/' + uploadFileName;

try {
    var s3 = Packages.com.amazonaws.services.s3.AmazonS3ClientBuilder.standard().withRegion('us-east-1').build();
    if (s3.doesObjectExist(uploadBucket, uploadKey)) {
        logger.info('Aetna SFTP Bridge: object already exists at ' + uploadBucket + '/' + uploadKey + ' - it will be replaced by this upload of ' + uploadFileName);
    }
} catch (existsErr) {
    // Best-effort visibility only - if the existence check itself fails, still proceed with
    // the upload below rather than blocking delivery on a check that isn't load-bearing.
    logger.info('Aetna SFTP Bridge: could not check whether ' + uploadBucket + '/' + uploadKey + ' already exists - ' + existsErr);
}

logger.info('Aetna SFTP Bridge: starting S3 upload - file=' + uploadFileName + ', target=' + uploadBucket + '/' + uploadKey);
return msg;

// Runs right after the native S3 write attempt completes, success or failure.
// response.getStatus() throws "TypeError: Cannot find function getStatus" on this
// Bridgelink instance's com.mirth.connect.server.userutil.ImmutableResponse (confirmed
// via testing - getStatus() is simply not exposed here even though it's a documented
// Response method). getError() and getMessage() work fine on the same object though, which
// matches the pattern already used for S3 writes elsewhere in the MCO channels (see
// Aetna.xml's responseTransformer scripts, which likewise only ever call response.getError()
// / response.getMessage() and never response.getStatus() - status checks there go through
// $('d7').getStatus(), i.e. getStatus() on an ImmutableConnectorMessage, not on the raw
// Response). So success/failure here is inferred from whether getError() returns anything.
// Each accessor is still wrapped separately since not every Response implementation
// necessarily exposes all of getError/getStatusMessage - one missing method should not
// hide the others or block this step from completing.
try {
    var uploadError = response.getError();
    if (uploadError) {
        logger.error('Aetna SFTP Bridge: S3 upload for ' + $('originalFilename') + ' failed - ' + uploadError);
    } else {
        logger.info('Aetna SFTP Bridge: S3 upload finished for ' + $('originalFilename') + ' with no error reported');
    }
} catch (e1) {
    logger.error('Aetna SFTP Bridge: could not read S3 upload error detail - ' + e1);
}
try {
    var uploadStatusMessage = response.getStatusMessage();
    if (uploadStatusMessage) {
        logger.info('Aetna SFTP Bridge: S3 upload status message - ' + uploadStatusMessage);
    }
} catch (e2) {
    // getStatusMessage may not be available on this Response implementation
}
return response;

properties.script:
// Runs once per file routed by the source script (one message per file - see Step 3).
// Checks whether the "Copy to Aetna Landing" destination (metaDataId 2) actually
// succeeded, and sends the step 1-3 error alert if the landing-directory write failed -
// the source script only catches failures reading/routing the file, not failures in this
// separate native destination, so that check has to happen here instead.
function sendAlertEmail(subject, body) {
    try {
        var smtpHostname = configurationMap.get('smtpHostName');
        var smtpPort = parseInt(configurationMap.get('smtpPort'));
        var smtpUsername = configurationMap.get('smtpUsername');
        var smtpPassword = configurationMap.get('smtpPassword');
        var fromEmail = configurationMap.get('smtpFromEmail');
        var toEmail = 'engineering@techbd.org';

        var smtpConn = SMTPConnection(smtpHostname, smtpPort, 0, true, 'TLS', smtpUsername, smtpPassword, fromEmail);
        smtpConn.send(toEmail, '', fromEmail, subject, body, 'UTF-8');
        logger.info('Aetna SFTP Bridge: alert email sent - ' + subject);
    } catch (mailErr) {
        logger.error('Aetna SFTP Bridge: failed to send alert email - ' + mailErr);
    }
}

var fileName = $('originalFilename');
var copyDest = $('d2');
var copyStatus = copyDest ? copyDest.getStatus() : null;
var copyFailed = copyStatus && copyStatus.toString() === 'ERROR';

// Pull whatever extra detail is available about the write outcome - wrapped separately
// since not every Response implementation exposes both accessors.
var copyStatusMessage = null;
try {
    copyStatusMessage = copyDest ? copyDest.getResponseStatusMessage() : null;
} catch (e1) {
    // getResponseStatusMessage may not be available on this ConnectorMessage implementation
}
var copyErrorDetail = null;
try {
    copyErrorDetail = copyDest ? copyDest.getResponseError() : null;
} catch (e2) {
    // getResponseError may not be available on this ConnectorMessage implementation
}

if (copyFailed) {
    logger.error('Aetna SFTP Bridge: delivery to the Aetna landing directory failed for ' + fileName + (copyStatusMessage ? ' - ' + copyStatusMessage : ''));
    if (copyErrorDetail) {
        logger.error('Aetna SFTP Bridge: landing-directory write error detail - ' + copyErrorDetail);
    }
    sendAlertEmail(
        'Aetna SFTP Bridge Alert: Error Copying File',
        'The Aetna landing directory write failed for ' + fileName + ' after it was read from Aetna\'s SFTP.\n\n' +
        (copyStatusMessage ? 'Status: ' + copyStatusMessage + '\n\n' : '') +
        (copyErrorDetail ? 'Error detail: ' + copyErrorDetail + '\n\n' : '') +
        'Check the "Copy to Aetna Landing" destination in the Aetna SFTP Bridge channel for the full message. Note the source file has already been moved to the /processed folder on Aetna\'s SFTP regardless of this failure.'
    );
} else {
    logger.info('Aetna SFTP Bridge: delivered ' + fileName + ' to the Aetna landing directory');
}
return;

channel.postprocessingScript:
// This script executes once after a message has been processed
// Responses returned from here will be stored as "Postprocessor" in the response map
return;

channel.deployScript:
// This script executes once when the channel is deployed
// You only have access to the globalMap and globalChannelMap here to persist data

globalMap.put("jbdcUrl", LookupHelper.get("Config-sensitive", "MC_JDBC_URL"));
globalMap.put("dbName", LookupHelper.get("Config-sensitive", "MC_JDBC_USERNAME"));
globalMap.put("dbPassword", LookupHelper.get("Config-sensitive", "MC_JDBC_PASSWORD"));
globalMap.put("s3BucketName", LookupHelper.get("Config-sensitive", "MC_S3_BUCKET_NAME"));

// Aetna's inbound SFTP login is username/password only - no key-based auth, so there is
// nothing to pull from Config-sensitive for the SFTP connection itself.

// Diagnostic-only: when aetnaSftpDebugLogging=true in the configuration map, install a
// JSch protocol-level logger so channel logs show the SSH/SFTP handshake and auth
// negotiation in detail (which auth methods the server offers, why each attempt is
// rejected, etc.). JSch.setLogger is a JVM-wide static setting, so this affects every
// channel on this Bridgelink instance that uses JSch while enabled - turn it back off
// (set the flag to anything other than "true", or remove it, and redeploy) once the
// connection issue is diagnosed.
if ("true".equalsIgnoreCase('' + configurationMap.get("aetnaSftpDebugLogging"))) {
    var jschLevelNames = ['DEBUG', 'INFO', 'WARN', 'ERROR', 'FATAL'];
    Packages.com.jcraft.jsch.JSch.setLogger(new Packages.com.jcraft.jsch.Logger({
        isEnabled: function(level) {
            return true;
        },
        log: function(level, message) {
            var levelName = jschLevelNames[level] || ('LEVEL_' + level);
            if (level >= 3) {
                logger.error('Aetna SFTP Bridge JSCH[' + levelName + ']: ' + message);
            } else {
                logger.info('Aetna SFTP Bridge JSCH[' + levelName + ']: ' + message);
            }
        }
    }));
    logger.info('Aetna SFTP Bridge: JSch protocol-level debug logging enabled');
} else {
    // JSch.setLogger has no "unset" - only "replace". If a previous deploy turned the flag
    // on, the verbose logger installed above stays active JVM-wide even after the flag is
    // turned back off, until something explicitly replaces it. This installs a no-op logger
    // so a redeploy with the flag off actually silences it, rather than leaving the earlier
    // deploy's verbose logger running indefinitely.
    Packages.com.jcraft.jsch.JSch.setLogger(new Packages.com.jcraft.jsch.Logger({
        isEnabled: function(level) {
            return false;
        },
        log: function(level, message) {
            // intentionally does nothing
        }
    }));
}

return;

channel.undeployScript:
// This script executes once when the channel is undeployed
// You only have access to the globalMap and globalChannelMap here to persist data
return;
